      <script>
        (function () {
          const tracks = Array.from(document.querySelectorAll(".recruitersTrack"));
          if (!tracks.length) return;

          const prevBtn = document.getElementById("recruitersPrev");
          const nextBtn = document.getElementById("recruitersNext");

          const transitionMs = 550;

          function getGapPx(item) {
            const style = window.getComputedStyle(item);
            return (parseFloat(style.marginLeft) || 0) + (parseFloat(style.marginRight) || 0);
          }

          function initInfiniteTrack(track) {
            const items = Array.from(track.children);
            if (items.length < 2) return null;

            const first = items[0];
            let itemWidth = first.getBoundingClientRect().width;
            let gap = getGapPx(first);

            // Clone items for seamless loop
            const viewport = track.parentElement;
            const viewportWidth = viewport.getBoundingClientRect().width;
            const clonesNeeded = Math.ceil(viewportWidth / (itemWidth + gap)) + 2;

            for (let i = 0; i < clonesNeeded; i++) {
              track.appendChild(items[i % items.length].cloneNode(true));
            }

            let x = 0;

            function stepPx() {
              const el = track.children[0];
              return el.getBoundingClientRect().width + getGapPx(el);
            }

            function apply(withTransition = true) {
              track.style.transition = withTransition
                ? `transform ${transitionMs}ms ease-in-out`
                : "none";
              track.style.transform = `translateX(${x}px)`;
            }

            function normalize() {
              const per = stepPx();
              const originalWidth = per * items.length;

              if (Math.abs(x) >= originalWidth) {
                x += originalWidth;
                apply(false);
              }
              if (x > 0) {
                x -= originalWidth;
                apply(false);
              }
            }

            function next() {
              x -= stepPx();
              apply(true);
              setTimeout(normalize, transitionMs + 20);
            }

            function prev() {
              x += stepPx();
              apply(true);
              setTimeout(normalize, transitionMs + 20);
            }

            window.addEventListener("resize", () => apply(false));

            return { next, prev };
          }

          // Init both rows independently
          const instances = tracks.map(initInfiniteTrack);

          // Manual controls move BOTH rows together
          prevBtn?.addEventListener("click", () => {
            instances.forEach(i => i?.prev());
          });

          nextBtn?.addEventListener("click", () => {
            instances.forEach(i => i?.next());
          });
        })();


        (function () {
          const root = document.querySelector('[data-accordion="curriculum"]');
          if (!root) return;

          const triggers = Array.from(root.querySelectorAll("[data-acc-trigger]"));

          function closeAll(exceptBtn = null) {
            triggers.forEach((btn) => {
              if (btn === exceptBtn) return;
              const panelId = btn.getAttribute("aria-controls");
              const panel = panelId ? document.getElementById(panelId) : null;
              btn.setAttribute("aria-expanded", "false");
              btn.closest("div.border")?.classList.remove("acc-open");
              if (panel) panel.hidden = true;
            });
          }

          triggers.forEach((btn) => {
            btn.addEventListener("click", () => {
              const panelId = btn.getAttribute("aria-controls");
              const panel = panelId ? document.getElementById(panelId) : null;
              if (!panel) return;

              const isOpen = btn.getAttribute("aria-expanded") === "true";

              // Single-open accordion behaviour:
              closeAll(btn);

              // Toggle current
              btn.setAttribute("aria-expanded", isOpen ? "false" : "true");
              btn.closest("div.border")?.classList.toggle("acc-open", !isOpen);
              panel.hidden = isOpen;
            });
          });
        })();


        /* video-modal.js */
        (function () {
          const modal = document.getElementById("videoModal");
          const frame = document.getElementById("videoModalFrame");
          const titleEl = document.getElementById("videoModalTitle");

          if (!modal || !frame) return;

          const triggers = Array.from(document.querySelectorAll("[data-modal-trigger]"));
          const closers = Array.from(document.querySelectorAll("[data-modal-close]"));

          function openModal(videoUrl, title) {
            if (titleEl) titleEl.textContent = title || "Success Story";
            frame.src = videoUrl;
            modal.classList.remove("hidden");
            modal.setAttribute("aria-hidden", "false");
            document.documentElement.style.overflow = "hidden";
          }


          function closeModal() {
            modal.classList.add("hidden");
            modal.setAttribute("aria-hidden", "true");
            document.documentElement.style.overflow = "";
            frame.src = "";
          }


          function onTriggerActivate(el) {
            const videoUrl = el.getAttribute("data-video");
            const title = el.getAttribute("data-title") || "Success Story";
            if (!videoUrl) return;
            openModal(videoUrl, title);
          }

          triggers.forEach((el) => {
            el.addEventListener("click", () => onTriggerActivate(el));
            el.addEventListener("keydown", (e) => {
              if (e.key === "Enter" || e.key === " ") {
                e.preventDefault();
                onTriggerActivate(el);
              }
            });
          });

          closers.forEach((el) => el.addEventListener("click", closeModal));

          document.addEventListener("keydown", (e) => {
            if (e.key === "Escape" && !modal.classList.contains("hidden")) closeModal();
          });
        })();


      </script>


