      <!-- --------Apply now----- -->
      <script>
        (function () {
          const btn = document.getElementById('floatingApplyNow');
          const formEl = document.querySelector('#apply-now');
          if (!btn || !formEl) return;

          const SHOW_AFTER_PX = 250; // show after user scrolls a bit
          let formInView = false;

          const io = new IntersectionObserver(
            (entries) => {
              formInView = entries[0].isIntersecting;
              update();
            },
            { root: null, threshold: 0.15 }
          );

          io.observe(formEl);

          function update() {
            const scrolled = window.scrollY > SHOW_AFTER_PX;

            // Visible only when scrolled AND form is NOT in view
            if (scrolled && !formInView) btn.classList.add('is-visible');
            else btn.classList.remove('is-visible');
          }

          window.addEventListener('scroll', update, { passive: true });
          window.addEventListener('resize', update);
          update();

          // Smooth scroll on click
          btn.addEventListener('click', function (e) {
            e.preventDefault();
            formEl.scrollIntoView({ behavior: 'smooth', block: 'start' });
            history.replaceState(null, '', '#apply-now');
          });
        })();
      </script>

      <!-- --------Apply now----- -->

      <!-- --------header-------- -->
      <script>
        (function () {
          const btn = document.getElementById("mobileMenuBtn");
          const menu = document.getElementById("mobileMenu");
          if (!btn || !menu) return;

          btn.addEventListener("click", () => {
            const isOpen = !menu.classList.contains("hidden");
            menu.classList.toggle("hidden");
            btn.setAttribute("aria-expanded", String(!isOpen));
          });

          menu.querySelectorAll("a").forEach((link) => {
            link.addEventListener("click", () => {
              menu.classList.add("hidden");
              btn.setAttribute("aria-expanded", "false");
            });
          });

          document.addEventListener("click", (e) => {
            if (!menu.contains(e.target) && !btn.contains(e.target)) {
              menu.classList.add("hidden");
              btn.setAttribute("aria-expanded", "false");
            }
          });
        })();
      </script>
