      <!-- Seend Form Data To Google Sheets  -->
      <script>
        function getUTM(param) {
          const params = new URLSearchParams(window.location.search);
          return params.get(param) || '';
        }
        const scriptURL = 'https://script.google.com/macros/s/AKfycbwmmNWR3s8LtRYZh-M6b0c3iyIIfQw6iZubkIpbftBycqfP6mvG9M6abS52eecNGSSv/exec';
        const form = document.getElementById('frmrlp-block-41');
        const btn = document.getElementById('form-submit-button');
        form.addEventListener('submit', e => {
          e.preventDefault();

          // UTM Capture Script 
          const fields = [
            "utm_source",
            "utm_medium",
            "utm_campaign",
            "utm_term",
            "utm_content",
            "utm_id"
          ];

          fields.forEach(name => {
            const input = form.querySelector(`[name="${name}"]`);
            if (input) {
              input.value = getUTM(name);
            }
          });

          if (btn) {
            btn.innerHTML = "Processing...";
            btn.disabled = true;
          }
          let submitted = false;
          const finalSubmit = () => {
            if (!submitted) {
              submitted = true;
              form.submit();
            }
          };
          setTimeout(finalSubmit, 2500);
          fetch(scriptURL, {
            method: 'POST',
            body: new FormData(form),
            mode: 'no-cors'
          })
            .then(() => {
              console.log("Sheet updated successfully");
              finalSubmit();
            })
            .catch(error => {
              console.error("Sheet Error:", error);
              finalSubmit();
            });
        });
      </script>

      <script>
        function loadDeferredScripts() {
          document.querySelectorAll('script[data-delay]').forEach(script => {
            const s = document.createElement('script');
            s.src = script.dataset.delay;
            s.defer = true;
            document.body.appendChild(s);
          });
        }

        ['scroll', 'mousemove', 'touchstart'].forEach(e =>
          window.addEventListener(e, loadDeferredScripts, { once: true })
        );
      </script>

